4263.sent:
// Log4Shell JNDI exploitation string in inbound IIS/app HTTP requests
let window = 7d;
W3CIISLog
| where TimeGenerated > ago(window)
| extend Combined = strcat(tostring(csUriStem), " ", tostring(csUriQuery), " ", tostring(csUserAgent), " ", tostring(csReferer))
| where Combined contains "jndi:"
    or Combined contains "%24%7b"            // URL-encoded ${
    or Combined matches regex @"(?i)(\$|%24)(\{|%7b)[^}]*(jndi|lower:|upper:|env:|sys:|date:|::-)"
| project TimeGenerated, Computer, sSiteName, cIP, csMethod, csUriStem, csUriQuery, csUserAgent, scStatus
| order by TimeGenerated desc

